import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.BUwdTBzS.js";const g=JSON.parse('{"title":"开发工作流","description":"","frontmatter":{"title":"开发工作流"},"headers":[],"relativePath":"dev-flow/references/skill-full.md","filePath":"dev-flow/references/skill-full.md","lastUpdated":null}'),l={name:"dev-flow/references/skill-full.md"};function r(a,e,i,s,n,h){return d(),t("div",null,[...e[0]||(e[0]=[c('<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/skill-full.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="开发工作流" tabindex="-1">开发工作流 <a class="header-anchor" href="#开发工作流" aria-label="Permalink to &quot;开发工作流&quot;">​</a></h1><p>面向 AI 辅助编程的系统化开发工作流与代码规范。本规范为最高优先级，必须严格遵守。</p><h2 id="统一流程设计" tabindex="-1">统一流程设计 <a class="header-anchor" href="#统一流程设计" aria-label="Permalink to &quot;统一流程设计&quot;">​</a></h2><blockquote><p><strong>核心理念</strong>：产出准确性是第一优先级。所有需求（无论大小）走同一条流程：阶段0（需求理解）→ 步骤1~3（研究→范围→方案）→ 步骤4（智能评估推荐执行深度）→ 执行。不再区分&quot;快速模式&quot;和&quot;完整模式&quot;，所有入口（<code>dev-flow</code> / <code>dev:</code>）等价进入统一流程，执行深度完全由步骤4基于研究成果智能评估推荐，用户可覆盖。</p></blockquote><h3 id="触发规则" tabindex="-1">触发规则 <a class="header-anchor" href="#触发规则" aria-label="Permalink to &quot;触发规则&quot;">​</a></h3><blockquote><p><strong>2026-06-01 改版</strong>：dev-flow 仅由<strong>显式命令</strong>触发或<strong>活跃流程相关恢复</strong>触发，AI 不再基于关键词主观判断自动触发。 单一权威源：<code>SKILL.md</code> §「触发规则」 + <code>.compiled/triggers.md</code> + <code>~/.codebuddy/rules/AI行为规范.mdc</code> §「Skill 触发检查」。</p></blockquote><h4 id="_1-显式触发-命中即-use-skill-dev-flow" tabindex="-1">1. 显式触发（命中即 <code>use_skill(&#39;dev-flow&#39;)</code>） <a class="header-anchor" href="#_1-显式触发-命中即-use-skill-dev-flow" aria-label="Permalink to &quot;1. 显式触发（命中即 `use_skill(&#39;dev-flow&#39;)`）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>用户输入</th><th>行为</th></tr></thead><tbody><tr><td><code>dev-flow</code> / <code>dev:</code> / <code>/dev-flow</code></td><td>进入统一流程，步骤4智能评估推荐执行深度</td></tr><tr><td><code>dev:kb</code> / <code>dev:k</code></td><td>知识库管理 → <code>use_skill(&#39;knowledge-loop&#39;)</code></td></tr><tr><td><code>dev:status</code> / <code>dev:st</code></td><td>工作上下文进度概览</td></tr><tr><td><code>dev:metrics</code> / <code>dev:m</code>（含 <code>--all</code> / <code>--trend</code> / <code>--report {ID}</code> / <code>--dashboard</code>）</td><td>度量查看</td></tr><tr><td><code>dev:onboard</code> / <code>dev:ob</code></td><td>知识库平台 profile 生成/刷新</td></tr><tr><td><code>dev:flowchart</code> / <code>dev:chart</code></td><td>生成/更新 dev-flow 流程图（md + html + png）</td></tr><tr><td><code>dev:ask</code> / <code>dev:guide</code></td><td>交互式功能菜单。加载 <code>references/menu.md</code>，弹出分类菜单，不进入步骤流程</td></tr><tr><td><code>dev:help</code> / <code>dev:h</code></td><td>显示帮助信息。加载 <code>references/help.md</code>，不进入步骤流程</td></tr><tr><td><code>--fast</code>（与基础命令组合）</td><td>修饰层：精简交互模式</td></tr><tr><td><code>--micro</code>（与基础命令组合）</td><td>基础模式：micro-fix（需满足阈值）</td></tr></tbody></table><blockquote><p><strong>命令规范</strong>： | &gt; | 命令 | 快捷 | 说明 | | &gt; |------|------|------| | &gt; | <code>--fast</code> | — | 附加精简交互模式（减少交互次数，可与任意命令组合） | | &gt; | <code>dev:kb</code> | <code>dev:k</code> | 知识库管理（查看/沉淀/扫描/搜索项目知识库） | | &gt; | <code>dev:status</code> | <code>dev:st</code> | 状态查看（当前工作上下文进度概览） | | &gt; | <code>dev:metrics</code> | <code>dev:m</code> | 度量查看（最近5次/全部/趋势/指定需求/仪表盘） | | &gt; | <code>dev:onboard</code> | <code>dev:ob</code> | 知识库平台 profile 生成/刷新/校验（L0 缓存）| | &gt; | <code>dev:flowchart</code> | <code>dev:chart</code> | 生成/更新 dev-flow 流程图（md + html + png） | <code>dev:</code> 前缀加不加 <code>/</code> 均可识别。<code>/dev-flow</code> 和 <code>dev-flow</code> 完全等价。 <strong>命令执行规范</strong>：</p><h4 id="dev-kb-dev-k" tabindex="-1"><code>dev:kb</code> / <code>dev:k</code> <a class="header-anchor" href="#dev-kb-dev-k" aria-label="Permalink to &quot;`dev:kb` / `dev:k`&quot;">​</a></h4><ol><li>确定当前项目名称（从最近的工作上下文或项目目录推断）</li><li><code>ls ~/.codebuddy/knowledge/{project-name}/</code> 列出已有知识</li><li>展示知识清单（模块名+覆盖主题+置信度+最后验证日期），弹出交互式选项：查看模块 / 扫描代码 / 检查健康度 / 搜索 / 返回</li><li>详细操作规则 → <code>use_skill(&#39;knowledge-loop&#39;)</code> 管理模式</li></ol><h4 id="dev-status-dev-st" tabindex="-1"><code>dev:status</code> / <code>dev:st</code> <a class="header-anchor" href="#dev-status-dev-st" aria-label="Permalink to &quot;`dev:status` / `dev:st`&quot;">​</a></h4><ol><li><code>ls ~/.codebuddy/working-context/.active-flows/</code> 扫描活跃流程</li><li><code>ls ~/.codebuddy/working-context/</code> 扫描工作上下文</li><li>展示：活跃需求清单（brief+当前步骤+模式+最后活跃时间）</li><li>展示：暂停需求清单（如有）</li><li>展示：最近完成的需求（最近3个，按文件修改时间排序）</li></ol><h4 id="dev-metrics-dev-m" tabindex="-1"><code>dev:metrics</code> / <code>dev:m</code> <a class="header-anchor" href="#dev-metrics-dev-m" aria-label="Permalink to &quot;`dev:metrics` / `dev:m`&quot;">​</a></h4><p>按 <code>references/metrics-rules.md</code>「用户命令」章节执行。支持 <code>--all</code>（全部历史）、<code>--trend</code>（趋势）、<code>--report {需求ID}</code>（指定需求）、<code>--dashboard</code>（生成并打开可视化仪表盘）。</p><h4 id="dev-onboard-dev-ob" tabindex="-1"><code>dev:onboard</code> / <code>dev:ob</code> <a class="header-anchor" href="#dev-onboard-dev-ob" aria-label="Permalink to &quot;`dev:onboard` / `dev:ob`&quot;">​</a></h4><ol><li>识别当前项目（参数 <code>--project=&lt;name&gt;</code> &gt; 工作上下文 &gt; <code>pwd</code> 推断）</li><li>读取 <code>references/remote-knowledge.md</code> 项目映射表（§二），未命中则提示&quot;项目未接入 知识库平台&quot;并退出</li><li>解析参数：无参数→智能判断；<code>--refresh</code>/<code>-r</code>→全量刷新；<code>--refresh-recent</code>/<code>-rr</code>→增量刷新；<code>--check</code>/<code>-c</code>→只校验不刷新</li><li>详细执行规范与 profile 新鲜度机制 → 读取 <code>references/onboard-flow.md</code></li></ol><h4 id="dev-flowchart-dev-chart" tabindex="-1"><code>dev:flowchart</code> / <code>dev:chart</code> <a class="header-anchor" href="#dev-flowchart-dev-chart" aria-label="Permalink to &quot;`dev:flowchart` / `dev:chart`&quot;">​</a></h4><ol><li>读取 <code>flowchart/SPEC.md</code> 获取版本信息 + 生成规范 + 模板</li><li>读取 <code>flowchart/README.md</code> 获取当前版本号</li><li>弹出交互式选项：选择更新方式（覆盖当前版本 / 另存新版本 / 取消）</li><li>按 SPEC.md §3 模板规范生成 <code>flowchart.md</code>（Mermaid 源码）</li><li>交互确认 flowchart.md 内容无误</li><li>按 SPEC.md §4 模板规范生成 <code>flowchart.html</code></li><li>Chrome headless 截图生成 <code>flowchart.png</code></li><li>可选：生成 <code>flowchart.svg</code>（需 mmdc）</li><li>若选「另存新版本」→ 更新 <code>flowchart/README.md</code> 版本信息</li></ol><blockquote><p>完整生成 Pipeline、Mermaid 规范、HTML 模板、CSS 变量 → <code>flowchart/SPEC.md</code></p></blockquote><h4 id="dev-help-dev-h" tabindex="-1"><code>dev:help</code> / <code>dev:h</code> <a class="header-anchor" href="#dev-help-dev-h" aria-label="Permalink to &quot;`dev:help` / `dev:h`&quot;">​</a></h4><ol><li><code>read_file(&quot;references/help.md&quot;)</code> 加载帮助内容</li><li>若带参数（如 <code>dev:help --micro</code>），从「命令详情」节定位对应条目输出</li><li>格式化输出，不创建工作上下文，不进入步骤流程</li></ol></blockquote><h4 id="_2-活跃流程恢复-自动触发-须双条件" tabindex="-1">2. 活跃流程恢复（自动触发，须双条件） <a class="header-anchor" href="#_2-活跃流程恢复-自动触发-须双条件" aria-label="Permalink to &quot;2. 活跃流程恢复（自动触发，须双条件）&quot;">​</a></h4><p><code>~/.codebuddy/working-context/.active-flows/{name}.flow</code> 存在 <strong>且</strong> 用户消息内容与该 <code>.flow</code> 的 <code>match_keywords</code> / <code>brief</code> <strong>相关</strong> → <code>use_skill(&#39;dev-flow&#39;)</code> → 走 v3 智能恢复网关（详见 <code>flow.md</code> §「启动模式识别」）。</p><blockquote><p>不相关时（如纯咨询、元讨论、其他需求）→ <strong>不触发恢复</strong>，普通对话推进。</p></blockquote><h4 id="_3-开发意图关键词-不自动触发-ai-主动建议" tabindex="-1">3. 开发意图关键词（<strong>不自动触发</strong>，AI 主动建议） <a class="header-anchor" href="#_3-开发意图关键词-不自动触发-ai-主动建议" aria-label="Permalink to &quot;3. 开发意图关键词（**不自动触发**，AI 主动建议）&quot;">​</a></h4><p>检测到以下开发意图关键词时，<strong>AI 不得自动调用 <code>use_skill(&#39;dev-flow&#39;)</code></strong>：</p><ul><li>开发：<code>新需求</code> / <code>需求开发</code> / <code>开发 xxx</code> / 任务平台 链接 / Figma 链接 / 含需求单格式内容</li><li>修复：<code>修复</code> / <code>解决</code> / <code>优化</code> / <code>调整</code> / <code>排查</code> / <code>重构</code> / <code>帮我改下</code> / <code>fix</code></li><li>收尾：<code>收尾</code> / <code>汇总改动</code> / <code>生成 commit</code></li></ul><p><strong>处理方式</strong>：</p><ol><li>在回复中<strong>主动建议一句</strong>：「检测到开发意图，建议输入 <code>dev-flow</code> 走完整流程，或直接说『直接改』我会按红线规范处理」</li><li><strong>等待用户决策</strong>，不自动进入 dev-flow，也不自动开始改代码</li><li>用户回复「直接改」 / 「不用走流程」 → 按 <code>~/.codebuddy/skills/dev-flow/references/no-dev-flow-mode.md</code> 执行（仍须遵守 <code>开发规范-红线.mdc</code> 12 条核心红线 + 前端编码底线）</li></ol><h4 id="_4-优先级" tabindex="-1">4. 优先级 <a class="header-anchor" href="#_4-优先级" aria-label="Permalink to &quot;4. 优先级&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户显式 dev-flow 命令</span></span>\n<span class="line"><span>&gt; 活跃流程恢复（相关时）</span></span>\n<span class="line"><span>&gt; issue-trace</span></span>\n<span class="line"><span>&gt; 普通对话（含开发意图建议）</span></span></code></pre></div><h4 id="_5-流程内信号-仅-dev-flow-已激活时生效" tabindex="-1">5. 流程内信号（仅 dev-flow 已激活时生效） <a class="header-anchor" href="#_5-流程内信号-仅-dev-flow-已激活时生效" aria-label="Permalink to &quot;5. 流程内信号（仅 dev-flow 已激活时生效）&quot;">​</a></h4><blockquote><p>以下信号<strong>仅在 dev-flow 已经触发后</strong>的流程内部生效，不属于&quot;触发规则&quot;。普通对话（dev-flow 未激活）时说这些词<strong>不会触发任何行为</strong>。</p></blockquote><ul><li><strong>迭代修复</strong>：<code>提测反馈了几个问题</code> / <code>测试提了 bug</code> / <code>继续上次的需求</code> / <code>后端接口好了</code> → 在已有 <code>.flow</code> 上下文中切换到 <code>iteration-fix</code> 模式（详见 <code>references/iteration-fix.md</code>）</li><li><strong>批次继续</strong>：<code>继续下一批</code> / <code>执行下一个批次</code> / <code>batch 2</code> → 在 <code>batch_mode: true &amp;&amp; status: batch_in_progress</code> 上下文中切换批次（详见 <code>references/iteration-fix.md</code> §「批次切换」）</li><li><strong>跨项目衔接</strong>：<code>跨项目修复衔接</code> / <code>跨项目验证衔接</code> / 含&quot;来源+工作上下文+根因&quot;结构化 prompt → 在 dev-flow 流程内加载 <code>references/cross-project-flow.md</code></li><li><strong>修饰层切换</strong>：<code>少问我</code> / <code>你决定就好</code> / <code>每步都问我</code> / <code>我要确认</code> → 在已激活流程中调整 <code>interaction_mode</code>（详见 <code>references/interaction-mode.md</code>）</li><li><strong>micro-fix 辅助描述</strong>：<code>改个错别字</code> / <code>这里少个分号</code> / <code>{文件}:{行号}</code> → 仅作为 <code>--micro</code> 命令的位置描述辅助（详见 <code>references/mode-matrix.md</code> §三bis）</li></ul><blockquote><p>⚠️ <strong>强制规则</strong>：上述自然语言信号<strong>不能单独触发 dev-flow</strong>。用户须先用 <code>dev-flow</code> / <code>dev:</code> / <code>--micro</code> 等显式命令进入 dev-flow，或命中活跃流程恢复，才会进入这些子流程。</p></blockquote><h4 id="_6-反绕过-强执行规则" tabindex="-1">6. 反绕过 &amp; 强执行规则 <a class="header-anchor" href="#_6-反绕过-强执行规则" aria-label="Permalink to &quot;6. 反绕过 &amp; 强执行规则&quot;">​</a></h4><ul><li>一旦显式命令触发 dev-flow，<strong>严格执行完整流程</strong>，不得以&quot;任务简单&quot;为由跳步。复杂度评估是步骤 4 的职责</li><li>步骤不可跳过：dev-flow 触发后，每个步骤必须按顺序执行</li><li>AI <strong>严禁</strong>基于关键词主观判断自动触发；命中开发意图关键词时必须先建议 <code>dev-flow</code> 命令</li><li>触发判断可观测性：消息含明显开发意图但 AI 未触发 dev-flow 时，必须在回复中<strong>显式提示用户</strong>有 <code>dev-flow</code> 命令可用</li></ul><h3 id="流程加载指令-prompt-chaining-架构" tabindex="-1">流程加载指令（Prompt Chaining 架构） <a class="header-anchor" href="#流程加载指令-prompt-chaining-架构" aria-label="Permalink to &quot;流程加载指令（Prompt Chaining 架构）&quot;">​</a></h3><p><strong>触发 dev-flow 后，统一加载流程定义文件</strong>：</p><table tabindex="0"><thead><tr><th>流程</th><th>加载文件</th><th>架构说明</th></tr></thead><tbody><tr><td>开发流程</td><td><code>read_file(&quot;flow.md&quot;)</code></td><td>L0 路由层（~340行），含阶段0+步骤1~10，步骤详细规范按需从 <code>steps/</code> 目录逐步加载</td></tr></tbody></table><p><strong>Prompt Chaining 执行协议</strong>（开发流程）：</p><ol><li>加载 <code>flow.md</code> 后，先 <code>read_file(&quot;steps/step-router.md&quot;)</code> 加载步骤路由器</li><li>每个步骤开始时：<code>read_file(&quot;steps/step-N-xxx.md&quot;)</code> 加载该步骤的详细规范</li><li>每个步骤完成后：输出结构化完成标记 JSON → 更新工作上下文 → 门控验证</li><li>门控通过后才能加载下一步骤文件</li><li>步骤 4 选择执行深度后，标准执行在步骤 7 结束，完整执行继续到步骤 10</li><li>❌ 禁止一次性加载多个步骤文件</li><li>❌ 禁止在未加载步骤文件的情况下执行该步骤</li><li>❌ 禁止跳过结构化完成标记 JSON 的输出</li></ol><h2 id="工作上下文持久化" tabindex="-1">工作上下文持久化 <a class="header-anchor" href="#工作上下文持久化" aria-label="Permalink to &quot;工作上下文持久化&quot;">​</a></h2><p>完整模板、字段说明、命名规则、创建/更新决策流程详见 <code>references/working-context.md</code>；活跃流程注册目录（<code>.active-flows/</code>）已拆出至 <code>references/active-flows.md</code>。</p><h3 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h3><ul><li><strong>文件位置</strong>：<code>~/.codebuddy/working-context/{YYYYMMDD}_{需求简述}_{项目缩写}.md</code><ul><li>单项目：项目缩写按映射表取值（如 <code>myProject</code>）</li><li>跨项目：项目缩写统一使用 <code>crossProject</code>（见 <code>references/cross-project-flow.md</code> §三）</li></ul></li><li><strong>创建前检查（强制）</strong>：先 <code>ls</code> 扫描目录 → 按关键词/任务 ID/分支名匹配 → 匹配到则更新，未匹配到则创建</li><li><strong>写入时机</strong>：阶段 0 写需求、用户纠正写约束、步骤 3 写计划、每步骤完成更新进度</li><li><strong>读取时机</strong>：每个步骤开始前必须先读取。优先级：约束与决策 &gt; 计划 &gt; 范围 &gt; 进度 &gt; 需求</li><li><strong>创建时</strong>：<code>read_file(&quot;references/working-context.md&quot;)</code> 加载完整模板</li><li>❌ 禁止不扫描目录就直接创建新文件</li><li>❌ 禁止同一需求创建多个文件</li></ul><h3 id="步骤切换门控-硬性规则-不可跳过" tabindex="-1">步骤切换门控（硬性规则，不可跳过） <a class="header-anchor" href="#步骤切换门控-硬性规则-不可跳过" aria-label="Permalink to &quot;步骤切换门控（硬性规则，不可跳过）&quot;">​</a></h3><p>步骤 N 完成后，必须先通过门控检查，才能进入步骤 N+1。门控未通过则阻塞。</p><p><strong>门控检查清单</strong>（每次步骤切换时强制执行）：</p><ol><li><strong>结构化完成标记已输出</strong>：当前步骤的完成标记 JSON 已输出</li><li><strong>进度已更新</strong>：步骤清单中当前步骤状态已更新</li><li><strong>当前状态已刷新</strong>：<code>## 进度 &gt; 当前状态</code> 已覆盖更新为下一步骤</li><li><strong>恢复指令已刷新</strong>：<code>## 进度 &gt; 恢复指令</code> 已覆盖更新</li></ol><p>门控为静默执行，仅在失败需要补更新时才产生额外动作。详见 <code>references/gate-validator.md</code>。</p><h3 id="跨会话恢复审计-强制" tabindex="-1">跨会话恢复审计（强制） <a class="header-anchor" href="#跨会话恢复审计-强制" aria-label="Permalink to &quot;跨会话恢复审计（强制）&quot;">​</a></h3><p>新会话中首次读取工作上下文后，必须先审计步骤清单（检查 ⚠️/❌ 标记），按恢复指令确定继续点。</p><h3 id="跨会话-devlog-同步检查" tabindex="-1">跨会话 devlog 同步检查 <a class="header-anchor" href="#跨会话-devlog-同步检查" aria-label="Permalink to &quot;跨会话 devlog 同步检查&quot;">​</a></h3><p>读取工作上下文后，如发现已完成的轮次但 devlog 缺少对应 Round 记录 → 在收尾阶段补全。静默执行。</p><h2 id="dev-flow-优先级与排除规则" tabindex="-1">dev-flow 优先级与排除规则 <a class="header-anchor" href="#dev-flow-优先级与排除规则" aria-label="Permalink to &quot;dev-flow 优先级与排除规则&quot;">​</a></h2><ol><li><strong>「需求开发」= 写代码</strong>，而非编写技术文档</li><li>文档类规则在 dev-flow 执行期间自动失效（除非用户明确要求）</li><li>参考文档是参考资料，不是创建指令</li><li>冲突时 dev-flow 胜出</li></ol><h2 id="git-分支命名规范" tabindex="-1">Git 分支命名规范 <a class="header-anchor" href="#git-分支命名规范" aria-label="Permalink to &quot;Git 分支命名规范&quot;">​</a></h2><p>详见 <code>references/shared-rules.md</code> §6。精要：<code>feature/</code> 新功能、<code>bugfix/</code> 修复、<code>feature_dev/&lt;功能&gt;/&lt;开发者&gt;</code> 孙分支；命名 ≤3 单词、小写短横线连接（禁驼峰/禁下划线）。 流程中两个触点： ① 阶段 0 仅当用户主动告知时记录 <code>branch_user_specified</code>（AI 不预告） ② <strong>步骤 4 §4.1 唯一定稿</strong>（计划锁定后、磁盘保存前，feature/ 场景同时推荐父+孙分支） ③ 步骤 4.5 <strong>纯校验</strong>（读取工作上下文 <code>branch</code> + <code>branch_dev</code>，父孙分支视为等价匹配）。</p><h2 id="ai-助手操作红线" tabindex="-1">AI 助手操作红线 <a class="header-anchor" href="#ai-助手操作红线" aria-label="Permalink to &quot;AI 助手操作红线&quot;">​</a></h2><p>见「开发规范-红线」操作红线章节（alwaysApply，每次对话已自动加载）。</p><h2 id="skill-优先级规则" tabindex="-1">Skill 优先级规则 <a class="header-anchor" href="#skill-优先级规则" aria-label="Permalink to &quot;Skill 优先级规则&quot;">​</a></h2><p>用户级 skill（<code>~/.codebuddy/skills/</code>）优先于项目级同名 skill。</p><h2 id="核心原则-18-条" tabindex="-1">核心原则（18 条） <a class="header-anchor" href="#核心原则-18-条" aria-label="Permalink to &quot;核心原则（18 条）&quot;">​</a></h2><blockquote><p>§1~§12 对应「开发规范-红线」的 12 条核心原则（alwaysApply，每次对话已自动加载）。§13~§18 为 dev-flow 补充原则，在 dev-flow 执行期间与红线等效。</p></blockquote><p><strong>红线层（§1~§12，alwaysApply）</strong>：需求理解优先 | 最小入侵 | 兼容性优先 | 根因定位与验证闭环 | 安全底线 | 副作用清理 | 边界条件与防御性编码 | 异步与竞态安全 | 错误处理 | 先搜索后编码 | 主动思考更优方案 | 上下文管理</p><p><strong>dev-flow 扩展层（§13~§18）</strong>：不确定就先确认 | 向用户解释 | 深度思考 | 不可变性优先 | 文件与函数大小约束 | 风格一致性</p><blockquote><p>💡 各原则的详细说明与示例 → <code>read_file(&quot;references/core-principles.md&quot;)</code>（按需查阅，日常执行参照上方精要即可）</p></blockquote><h2 id="交互模式-精简交互" tabindex="-1">交互模式（精简交互） <a class="header-anchor" href="#交互模式-精简交互" aria-label="Permalink to &quot;交互模式（精简交互）&quot;">​</a></h2><p>支持标准模式（默认）和精简模式（仅关键决策点暂停）。精简模式按风险等级分级处理。详见 <code>references/interaction-mode.md</code>。</p><h2 id="并行执行策略-环境感知多模式" tabindex="-1">并行执行策略（环境感知多模式） <a class="header-anchor" href="#并行执行策略-环境感知多模式" aria-label="Permalink to &quot;并行执行策略（环境感知多模式）&quot;">​</a></h2><p>首次并行调度前执行平台能力检测，根据检测结果自动选择执行模式：</p><ul><li><strong>模式 A（并行工具调用）</strong>：单 Agent 环境默认模式，通过并行工具调用实现任务并行，角色标注仅作思维引导</li><li><strong>模式 B（多 Agent 协作）</strong>：Claude Code / WorkBuddy / OpenClaw 等支持独立 Agent 实例的环境，完整角色定义生效</li><li><strong>CodeBuddy 子代理模式</strong>：通过 <code>Task</code> 工具调用 <code>agents/</code> 下的自定义 Agent（1号~9号），子 Agent 只读，写入由主 Agent 串行执行</li></ul><p>检测规则（含 CodeBuddy 检测项）、调度策略、成本感知、结果冲突检测、角色定义、防误判规则详见 <code>references/shared-rules.md</code> §3。</p><h2 id="skill-自动发现-借鉴-superpowers" tabindex="-1">Skill 自动发现（借鉴 Superpowers） <a class="header-anchor" href="#skill-自动发现-借鉴-superpowers" aria-label="Permalink to &quot;Skill 自动发现（借鉴 Superpowers）&quot;">​</a></h2><blockquote><p>核心理念：哪怕只有 1% 的可能性某个 Skill 能帮助当前任务，也应该主动检查并调用。</p></blockquote><p>完整的步骤×Skill 匹配表详见 <code>references/shared-rules.md</code> §5（单一真相源）。</p><p>静默评估，主动建议，不阻塞主流程，已在上下文中的 Skill 不重复加载。</p><h2 id="commit-message-生成" tabindex="-1">Commit Message 生成 <a class="header-anchor" href="#commit-message-生成" aria-label="Permalink to &quot;Commit Message 生成&quot;">​</a></h2><p>详见 <code>references/shared-rules.md</code> §1。精要：</p><ol><li>复用检查（工作上下文 <code>## 交付</code> 区块）→ 2. 调用 <code>use_skill(&#39;smart-commit&#39;)</code> → 3. 用户确认（✅确认/✏️修改/🔄重新生成/📦确认并提交）→ 4. 持久化到工作上下文</li></ol><table tabindex="0"><thead><tr><th>模式</th><th>触发位置</th></tr></thead><tbody><tr><td>标准执行</td><td>步骤 7（清理+Commit）/ 步骤 6C 暂存场景</td></tr><tr><td>完整执行</td><td>步骤 10（归档与交付）</td></tr></tbody></table><p>仅生成，❌ 禁止自动执行 <code>git commit</code>（除非用户选择「📦 确认并提交」）。格式：<code>&lt;type&gt;: &lt;description&gt;</code>（无 scope）</p><h2 id="对话窗口-token-管理" tabindex="-1">对话窗口 Token 管理 <a class="header-anchor" href="#对话窗口-token-管理" aria-label="Permalink to &quot;对话窗口 Token 管理&quot;">​</a></h2><p>对话中后期按需加载 → <code>read_file(&quot;references/token-management.md&quot;)</code>。核心：&gt;15 轮主动压缩，&gt;25 轮强制精简。</p><h2 id="开发日志" tabindex="-1">开发日志 <a class="header-anchor" href="#开发日志" aria-label="Permalink to &quot;开发日志&quot;">​</a></h2><p>详见 <code>references/devlog-rules.md</code>（按需加载）。</p><h2 id="项目知识库-project-knowledge-base" tabindex="-1">项目知识库（Project Knowledge Base） <a class="header-anchor" href="#项目知识库-project-knowledge-base" aria-label="Permalink to &quot;项目知识库（Project Knowledge Base）&quot;">​</a></h2><p>调用 <code>use_skill(&#39;knowledge-loop&#39;)</code> 管理项目级应用知识库（<code>~/.codebuddy/knowledge/</code>）。 支持检索模式（步骤1/5）、沉淀模式（步骤7/10/收尾）、管理模式（<code>dev:kb</code> 命令集）。 详见独立 Skill <code>knowledge-loop</code>。</p><h2 id="知识库平台-知识库-mcp-项目级权威" tabindex="-1">知识库平台 知识库（MCP，项目级权威） <a class="header-anchor" href="#知识库平台-知识库-mcp-项目级权威" aria-label="Permalink to &quot;知识库平台 知识库（MCP，项目级权威）&quot;">​</a></h2><p>与本地 <code>knowledge-loop</code> 互补：本地是 AI 的&quot;肌肉记忆&quot;（易错点/坑），知识库平台 是项目的&quot;全景地图&quot;（源码/架构 wiki/commit/MR）。</p><h3 id="v2-节点信号触达-替代-v1-cache-档位驱动" tabindex="-1">v2 节点信号触达（替代 v1 CACHE 档位驱动） <a class="header-anchor" href="#v2-节点信号触达-替代-v1-cache-档位驱动" aria-label="Permalink to &quot;v2 节点信号触达（替代 v1 CACHE 档位驱动）&quot;">​</a></h3><p>知识库平台 定位为<strong>节点级外援</strong>而非默认加载的知识源，遵循&quot;按节点按需触达 + 按数据类型精选&quot;：</p><ul><li><strong>本地 profile</strong>（零 MCP）：<code>~/.codebuddy/knowledge/{project}/_profile.md</code>，<code>dev:onboard</code> 生成，阶段 0.5 仅在本地 profile 存在且未过期时注入</li><li><strong>有域检索</strong>（传 <code>search_domain</code>）：信号 1/2/3/5 命中时用于限定当前项目</li><li><strong>全库检索</strong>（不传 <code>search_domain</code>）：信号 4 跨项目联调专用</li></ul><p>完整节点触达策略与收益量化 → <code>references/remote-knowledge.md</code> §三 / §六</p><h3 id="配置与触发" tabindex="-1">配置与触发 <a class="header-anchor" href="#配置与触发" aria-label="Permalink to &quot;配置与触发&quot;">​</a></h3><ul><li><strong>项目映射表</strong>：<code>references/remote-knowledge.md</code> §二（必须已注册才能启用，未注册则静默跳过）</li><li><strong>节点信号与 CLI 覆盖</strong>：<code>references/remote-knowledge.md</code> §一 / §四 4.3（v2 信号驱动：信号 1首次接触陌生模块 / 信号 2历史 MR / 信号 3bugfix 踩坑 / 信号 4跨项目 / 信号 5commit 风格，默认沉默）</li><li><strong>profile 生命周期</strong>：<code>references/onboard-flow.md</code>（新鲜度、漂移检测、3 档刷新粒度、10 个兼容场景）</li></ul><h3 id="挂载点" tabindex="-1">挂载点 <a class="header-anchor" href="#挂载点" aria-label="Permalink to &quot;挂载点&quot;">​</a></h3><ul><li><strong>阶段 0.5（项目画像轻量注入）</strong>：v2 默认沉默；仅当本地 <code>_profile.md</code> 存在且未过期时读取注入，0 MCP 调用</li><li><strong>步骤 1（研究定位）</strong>：默认纯本地检索；仅命中信号 1（首次接触陌生模块）或信号 4（跨项目联调）时触发 MCP</li><li><strong>步骤 3（制定方案）</strong>：仅命中信号 2（需求含扩展类动词且项目接入 知识库平台）时拉取历史类似 MR 作方案参考</li><li><strong>步骤 9（反思与学习）</strong>：仅命中信号 3（need_type=bugfix）时查 git_doc_platform 常见问题/历史坑</li></ul><h3 id="降级与来源标注" tabindex="-1">降级与来源标注 <a class="header-anchor" href="#降级与来源标注" aria-label="Permalink to &quot;降级与来源标注&quot;">​</a></h3><ul><li><strong>降级策略</strong>：本轮对话内失败即跳过，不做持久化熔断；本地流程是稳定底线</li><li><strong>来源标注</strong>：步骤 1 表格必须标注 <code>[local]/[remote-kb/git]/[remote-kb/wiki]/[remote-kb/commit]/[knowledge]</code> 等来源标签</li><li><strong>交叉验证</strong>：MCP 命中的文件路径必须用 <code>read_file</code> 验证真实存在（防索引延迟）</li></ul><h2 id="跨项目联调-cross-project-flow" tabindex="-1">跨项目联调（Cross-Project Flow） <a class="header-anchor" href="#跨项目联调-cross-project-flow" aria-label="Permalink to &quot;跨项目联调（Cross-Project Flow）&quot;">​</a></h2><p>当修复目标不在当前项目时（如组件库 bug 需要在组件库仓库修复，再回消费方项目验证），自动触发跨项目流程。 详见 <code>references/cross-project-flow.md</code>（按需加载）。</p><p><strong>挂载点</strong>：</p><ul><li><strong>步骤 2（范围确认）</strong>：检测到修改目标不在当前 workspace → 标记 <code>cross_project</code>，生成 B 项目衔接 prompt</li><li><strong>步骤 6C（联调）</strong>：检测到 <code>cross_project</code> 标记 → 扩展为跨项目联调选项，生成 A 项目验证 prompt</li><li><strong>B 项目新对话</strong>：识别衔接 prompt → 从 A 项目工作上下文继承根因和方案，跳过重复研究</li></ul><p><strong>不动主干</strong>：不新增步骤编号，通过钩子在已有节点按需触发，非跨项目场景零开销。</p><h2 id="迭代修复机制" tabindex="-1">迭代修复机制 <a class="header-anchor" href="#迭代修复机制" aria-label="Permalink to &quot;迭代修复机制&quot;">​</a></h2><p>检测到迭代修复信号后 → <code>read_file(&quot;references/iteration-fix.md&quot;)</code> 加载完整流程。 触发条件：匹配到已有工作上下文 + 进度显示上一轮已完成。</p><h2 id="figma-设计稿处理流程" tabindex="-1">Figma 设计稿处理流程 <a class="header-anchor" href="#figma-设计稿处理流程" aria-label="Permalink to &quot;Figma 设计稿处理流程&quot;">​</a></h2><p>用户提供 Figma 链接时 → <code>read_file(&quot;references/figma-flow.md&quot;)</code> 加载完整处理流程。</p><h2 id="文档同步" tabindex="-1">文档同步 <a class="header-anchor" href="#文档同步" aria-label="Permalink to &quot;文档同步&quot;">​</a></h2><p>详见 <code>references/doc-sync-rules.md</code>（按需加载）。</p><h2 id="技术方案文档生成-更新" tabindex="-1">技术方案文档生成/更新 <a class="header-anchor" href="#技术方案文档生成-更新" aria-label="Permalink to &quot;技术方案文档生成/更新&quot;">​</a></h2><p>完整流程详见 <code>references/tech-proposal-flow.md</code>。核心：已有则更新，没有才新建。</p><h2 id="专题规范" tabindex="-1">专题规范 <a class="header-anchor" href="#专题规范" aria-label="Permalink to &quot;专题规范&quot;">​</a></h2><p>遇到对应场景时 → <code>read_file(&quot;references/topic-specs.md&quot;)</code> 加载完整专题规范查找表。</p><h2 id="模式矩阵-6-种基础模式-1-种修饰层" tabindex="-1">模式矩阵（6 种基础模式 + 1 种修饰层） <a class="header-anchor" href="#模式矩阵-6-种基础模式-1-种修饰层" aria-label="Permalink to &quot;模式矩阵（6 种基础模式 + 1 种修饰层）&quot;">​</a></h2><p>dev-flow 采用<strong>两个独立维度</strong>描述执行状态：</p><ul><li><strong>基础模式</strong>（<code>mode</code>，互斥单选）：<code>standard</code> / <code>full</code> / <code>iteration-fix</code> / <code>batch</code> / <code>cross-project</code>；另设专项轻量模式 <code>micro-fix</code>（适用于 ≤3 文件对称修改 + ≤10 行/文件 + 已知位置的快速修复）</li><li><strong>修饰层</strong>（<code>interaction_mode</code>，正交叠加在任一基础模式之上）：<code>streamlined</code>（仅调节交互频率，不改变步骤覆盖、reference 加载或输出 schema）</li></ul><p>当 AI 不确定当前模式、多模式信号冲突、或用户询问模式切换规则时 → <code>read_file(&quot;references/mode-matrix.md&quot;)</code> 加载单一真相源（含模式分类表 + 决策树 + 步骤覆盖矩阵 + micro-fix 专项说明 §三bis + 修饰层详规 §九 + 优先级规则）。</p>',109)])])}const p=o(l,[["render",r]]);export{g as __pageData,p as default};
